'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api).sort(), ['handleDefect']);
const { handleDefect } = api;
assert.equal(typeof handleDefect, 'function');

const original = [
  { key: 3, summary: 'third', details: 'd3', phase: 'resolved' },
  { key: 1, summary: 'first', details: 'd1', phase: 'queued' }
];
const snapshot = JSON.stringify(original);
const listed = handleDefect(original, { type: 'list' });
assert.equal(listed.status, 200);
assert.deepEqual(listed.body, [original[1], original[0]]);
assert.deepEqual(listed.state, original);
assert.equal(JSON.stringify(original), snapshot);
assert.notStrictEqual(listed.body, listed.state);
assert.notStrictEqual(listed.body[0], listed.state[1]);
assert.notStrictEqual(listed.state[0], original[0]);
listed.body[0].summary = 'changed';
assert.equal(listed.state[1].summary, 'first');
assert.equal(original[1].summary, 'first');

const got = handleDefect(original, { type: 'get', key: 3 });
assert.deepEqual(got, {
  status: 200,
  body: { key: 3, summary: 'third', details: 'd3', phase: 'resolved' },
  state: original
});
assert.notStrictEqual(got.body, got.state[0]);
assert.notStrictEqual(got.state[0], original[0]);

assert.deepEqual(handleDefect(original, { type: 'get', key: 2 }), {
  status: 404,
  body: { error: 'Defect not found' },
  state: original
});

const addedRecord = { key: 2, summary: 'second', details: 'd2', phase: 'active' };
const added = handleDefect(original, { type: 'add', record: addedRecord });
assert.equal(added.status, 201);
assert.deepEqual(added.body, addedRecord);
assert.deepEqual(added.state, [...original, addedRecord]);
assert.notStrictEqual(added.body, added.state[2]);
assert.notStrictEqual(added.state[2], addedRecord);
addedRecord.summary = 'input changed';
assert.equal(added.body.summary, 'second');
assert.equal(added.state[2].summary, 'second');

assert.deepEqual(handleDefect(original, {
  type: 'add',
  record: { key: 1, summary: 'duplicate', details: 'x', phase: 'queued' }
}), {
  status: 409,
  body: { error: 'Duplicate key' },
  state: original
});

for (const record of [
  { key: 0, summary: 's', details: 'd', phase: 'queued' },
  { key: 1.2, summary: 's', details: 'd', phase: 'queued' },
  { key: 2, summary: '', details: 'd', phase: 'queued' },
  { key: 2, summary: 's', details: '', phase: 'queued' },
  { key: 2, summary: 's', details: 'd', phase: 'other' }
]) {
  const response = handleDefect(original, { type: 'add', record });
  assert.equal(response.status, 400);
  assert.deepEqual(response.body, { error: 'Invalid input' });
  assert.deepEqual(response.state, original);
}

for (const command of [null, {}, { type: 'unknown' }, { type: 'get', key: 0 }, { type: 'add' }]) {
  const response = handleDefect(original, command);
  assert.equal(response.status, 400);
  assert.deepEqual(response.body, { error: 'Invalid input' });
  assert.deepEqual(response.state, original);
}

for (const badState of [null, {}, [{ key: -1, summary: 's', details: 'd', phase: 'queued' }]]) {
  assert.deepEqual(handleDefect(badState, { type: 'list' }), {
    status: 400,
    body: { error: 'Invalid input' },
    state: []
  });
}

assert.deepEqual(handleDefect([], { type: 'list' }), { status: 200, body: [], state: [] });

